#!/usr/bin/env python3
"""Tiny static site generator. Standard library only.

Usage:  python build.py
Output: ./public/  (open public/index.html, or upload the folder to any static host)
"""
from pathlib import Path
from html import escape

OUT = Path("public")

SITE = {
    "title": "My Static Site",
    "nav": [("Home", "index.html"), ("About", "about.html"), ("Projects", "projects.html")],
}

PAGES = {
    "index.html": {
        "heading": "Welcome",
        "body": ["This site was generated by a single Python script.", "Edit build.py, run it again, and the pages are rebuilt."],
    },
    "about.html": {
        "heading": "About",
        "body": ["Write something about yourself here."],
    },
    "projects.html": {
        "heading": "Projects",
        "body": ["Project one", "Project two", "Project three"],
    },
}

CSS = """
body{font-family:system-ui,sans-serif;max-width:720px;margin:0 auto;padding:1rem;line-height:1.6;color:#222}
nav a{margin-right:1rem;text-decoration:none;color:#0a58ca}
nav a:hover{text-decoration:underline}
footer{margin-top:3rem;font-size:.85rem;color:#777}
"""

TEMPLATE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{page_title} | {site_title}</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<nav>{nav}</nav>
<h1>{heading}</h1>
{body}
<footer>Built with Python</footer>
</body>
</html>
"""


def render(page: dict) -> str:
    nav = "".join(f'<a href="{href}">{escape(label)}</a>' for label, href in SITE["nav"])
    body = "\n".join(f"<p>{escape(p)}</p>" for p in page["body"])
    return TEMPLATE.format(
        page_title=escape(page["heading"]),
        site_title=escape(SITE["title"]),
        nav=nav,
        heading=escape(page["heading"]),
        body=body,
    )


def main() -> None:
    OUT.mkdir(exist_ok=True)
    (OUT / "style.css").write_text(CSS.strip(), encoding="utf-8")
    for name, page in PAGES.items():
        (OUT / name).write_text(render(page), encoding="utf-8")
        print(f"built {OUT / name}")


if __name__ == "__main__":
    main()
